26	/**
27	 * Enforces that a newly created owner does not reuse another owner's telephone. The telephone
28	 * has already been normalized (non-digits stripped to ten digits) by the field validation advice,
29	 * so a plain equality comparison against the stored owners is sufficient. Updates to an existing
30	 * owner keep their own number and are left untouched.
31	 */
32	@Aspect
33	@Component
34	public class OwnerTelephoneUniquenessAspect {
35	
36	    private final OwnerRepository ownerRepository;
37	
38	    public OwnerTelephoneUniquenessAspect(OwnerRepository ownerRepository) {
39	        this.ownerRepository = ownerRepository;
40	    }
41	
42	    @Before("execution(* org.springframework.samples.petclinic.service.ClinicService.saveOwner(..)) && args(owner)")
43	    public void rejectDuplicateTelephone(Owner owner) {
44	        String telephone = owner.getTelephone();
45	        if (!owner.isNew() || telephone == null) {
46	            return;
47	        }
48	        boolean taken = ownerRepository.findAll().stream()
49	            .anyMatch(existing -> telephone.equals(existing.getTelephone()));
50	        if (taken) {
51	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Telephone already in use by another owner");
52	        }
53	    }
54	}
