18	
19	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
20	import org.springframework.validation.Errors;
21	import org.springframework.validation.Validator;
22	import org.springframework.web.bind.WebDataBinder;
23	import org.springframework.web.bind.annotation.ControllerAdvice;
24	import org.springframework.web.bind.annotation.InitBinder;
25	
26	/**
27	 * Rejects an owner whose required text fields are missing or blank. Each offending field is
28	 * reported through the standard validation flow so its name appears in the 400 response.
29	 */
30	@ControllerAdvice
31	public class OwnerFieldsValidationAdvice implements Validator {
32	
33	    @InitBinder
34	    void registerOwnerFieldsValidator(WebDataBinder binder) {
35	        binder.addValidators(this);
36	    }
37	
38	    @Override
39	    public boolean supports(Class<?> clazz) {
40	        return OwnerFieldsDto.class.isAssignableFrom(clazz);
41	    }
42	
43	    @Override
44	    public void validate(Object target, Errors errors) {
45	        OwnerFieldsDto owner = (OwnerFieldsDto) target;
46	        rejectIfBlank(errors, "firstName", owner.getFirstName());
47	        rejectIfBlank(errors, "lastName", owner.getLastName());
48	        rejectIfBlank(errors, "address", owner.getAddress());
49	        rejectIfBlank(errors, "city", owner.getCity());
50	        rejectIfBlank(errors, "telephone", owner.getTelephone());
51	        normalizeTelephone(errors, owner);
52	    }
53	
54	    private void rejectIfBlank(Errors errors, String field, String value) {
55	        if (value == null || value.isBlank()) {
56	            errors.rejectValue(field, "required", "must not be blank");
57	        }
58	    }
59	
60	    /**
61	     * Normalizes the telephone to E.164 form, storing it back on the payload so it is persisted
62	     * and echoed as-is; rejects the field when no valid E.164 number can be formed.
63	     */
64	    private void normalizeTelephone(Errors errors, OwnerFieldsDto owner) {
65	        if (owner.getTelephone() == null) {
66	            return;
67	        }
68	        String e164 = E164Telephone.toE164(owner.getTelephone());
69	        if (e164 != null) {
70	            owner.setTelephone(e164);
71	        } else {
72	            errors.rejectValue("telephone", "telephone.invalid", "must be a valid E.164 telephone");
73	        }
74	    }
75	}
