23	import org.springframework.stereotype.Component;
24	import org.springframework.web.server.ResponseStatusException;
25	
26	/**
27	 * Rejects creating an owner who shares another owner's household, i.e. the same last name and the
28	 * same address compared case-insensitively with runs of whitespace collapsed. The check is skipped
29	 * when the request explicitly opts in with {@code sharesHousehold} set to true.
30	 */
31	@Aspect
32	@Component
33	public class OwnerHouseholdUniquenessAdvice {
34	
35	    private final ClinicService clinicService;
36	
37	    public OwnerHouseholdUniquenessAdvice(ClinicService clinicService) {
38	        this.clinicService = clinicService;
39	    }
40	
41	    @Before("execution(* org.springframework.samples.petclinic.rest.controller.v1.OwnerRestControllerV1.addOwner(..)) && args(fields)")
42	    public void rejectDuplicateHousehold(OwnerFieldsDto fields) {
43	        if (Boolean.TRUE.equals(fields.getSharesHousehold())) {
44	            return;
45	        }
46	        String lastName = normalize(fields.getLastName());
47	        String address = normalize(fields.getAddress());
48	        if (lastName == null || address == null) {
49	            return;
50	        }
51	        boolean taken = clinicService.findAllOwners().stream().anyMatch(existing ->
52	            lastName.equals(normalize(existing.getLastName())) && address.equals(normalize(existing.getAddress())));
53	        if (taken) {
54	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Another owner already shares this household");
55	        }
56	    }
57	
58	    private static String normalize(String value) {
59	        return value == null ? null : value.strip().replaceAll("\\s+", " ").toLowerCase();
60	    }
61	}
